// ByWorkstreamField orders the results by workstream field.
func ByWorkstreamField(field string, opts ...sql.OrderTermOption) OrderOption {
	return func(s *sql.Selector) {
		sqlgraph.OrderByNeighborTerms(s, newWorkstreamStep(), sql.OrderByField(field, opts...))
	}
}

// ByLatestEvidenceField orders the results by latest_evidence field.
func ByLatestEvidenceField(field string, opts ...sql.OrderTermOption) OrderOption {
	return func(s *sql.Selector) {
		sqlgraph.OrderByNeighborTerms(s, newLatestEvidenceStep(), sql.OrderByField(field, opts...))
	}
}
func newWorkstreamStep() *sqlgraph.Step {
	return sqlgraph.NewStep(
		sqlgraph.From(Table, FieldID),
		sqlgraph.To(WorkstreamInverseTable, FieldID),
		sqlgraph.Edge(sqlgraph.M2O, false, WorkstreamTable, WorkstreamColumn),
	)
}
func newLatestEvidenceStep() *sqlgraph.Step {
	return sqlgraph.NewStep(
		sqlgraph.From(Table, FieldID),
		sqlgraph.To(LatestEvidenceInverseTable, FieldID),
		sqlgraph.Edge(sqlgraph.M2O, false, LatestEvidenceTable, LatestEvidenceColumn),
	)
}
